(()=>{const r=document.querySelector('.smg-foundation-modules');if(!r||typeof smgFoundationModules==='undefined')return;const c=[...r.querySelectorAll('.smg-foundation-card')],s=r.querySelector('#smg-foundation-search');let g='all',t='all';const a=()=>{const q=(s?.value||'').trim().toLowerCase();c.forEach(e=>{e.hidden=!((g==='all'||e.dataset.category===g)&&(t==='all'||e.dataset.status===t)&&(!q||(e.dataset.search||'').includes(q)))})};r.querySelectorAll('.smg-foundation-sidebar button').forEach(b=>b.addEventListener('click',()=>{r.querySelectorAll('.smg-foundation-sidebar button').forEach(x=>x.classList.remove('is-active'));b.classList.add('is-active');g=b.dataset.category;a()}));r.querySelectorAll('.smg-foundation-toolbar button').forEach(b=>b.addEventListener('click',()=>{r.querySelectorAll('.smg-foundation-toolbar button').forEach(x=>x.classList.remove('is-active'));b.classList.add('is-active');t=b.dataset.status;a()}));s?.addEventListener('input',a);r.querySelectorAll('.smg-foundation-toggle').forEach(i=>i.addEventListener('change',async()=>{const card=i.closest('.smg-foundation-card');i.disabled=true;const body=new URLSearchParams({action:smgFoundationModules.action,nonce:smgFoundationModules.nonce,module:i.value,enabled:String(i.checked)});try{const response=await fetch(smgFoundationModules.ajaxUrl,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8'},body});const result=await response.json();if(!result.success)throw new Error(result?.data?.message||'Unable to update module.');card.dataset.status=i.checked?'active':'inactive';a()}catch(error){i.checked=!i.checked;window.alert(error.message)}finally{i.disabled=false}}))})();